begin;

do $review_guard$
begin
  if (
    select count(*)
    from public.self_host_apps a
    where a.published = true
      and a.self_hosting_status = 'self_hostable'
      and (
        (a.slug = 'grafanamimir' and a.requires_database is null and a.storage_profile = 'unknown' and a.persistent_storage is null)
        or (a.slug = 'grafanapromtail' and a.source_code_url = 'https://github.com/grafana/loki/tree/main/clients/cmd/promtail' and a.requires_database is null and a.storage_profile = 'unknown' and a.persistent_storage is null and a.docker_support = 'community' and a.maintenance_status = 'active')
        or (a.slug = 'kibana' and a.docker_image = 'docker.elastic.co/kibana/kibana:9.5.4' and a.requires_database = true and a.database_types = array['elasticsearch']::text[] and a.storage_profile = 'unknown' and a.persistent_storage is null and a.ram_recommended_mb is null and a.resource_requirement_kind = 'unknown')
        or (a.slug = 'neo4j' and a.requires_database is null and a.storage_profile = 'unknown' and a.persistent_storage is null and a.compose_support = false and a.compose_url is null and a.ram_min_mb is null and a.ram_recommended_mb is null and a.storage_min_gb is null and a.resource_requirement_kind = 'unknown')
        or (a.slug = 'postgis' and a.requires_database = true and a.database_types = array['postgres']::text[] and a.storage_profile = 'unknown' and a.persistent_storage is null)
        or (a.slug = 'prom-alertmanager' and a.requires_database is null and a.storage_profile = 'unknown' and a.persistent_storage is null)
        or (a.slug = 'rancher' and a.requires_database is null and a.storage_profile = 'unknown' and a.persistent_storage is null)
        or (a.slug = 'plex' and a.requires_database is null and a.storage_profile = 'unknown' and a.persistent_storage = true)
        or (a.slug = 'collabora-code' and a.requires_database is null and a.storage_profile = 'unknown' and a.persistent_storage is null and a.docker_support = 'community')
        or (a.slug = 'swag' and a.docker_url = 'https://hub.docker.com/r/linuxserver/swag' and a.docker_image = 'linuxserver/swag' and a.docs_url = 'https://github.com/linuxserver/docker-swag#readme' and a.install_docs_url = 'https://github.com/linuxserver/docker-swag#readme' and a.compose_support = false and a.compose_url is null and a.requires_database is null and a.storage_profile = 'unknown' and a.persistent_storage is null and a.docker_support = 'community')
        or (a.slug = 'chronograf' and a.requires_database is null and a.storage_profile = 'unknown' and a.persistent_storage is null)
        or (a.slug = 'watchtower' and a.requires_database is null and a.storage_profile = 'unknown' and a.persistent_storage is null and a.maintenance_status = 'archived' and a.docker_support = 'community')
      )
  ) <> 12 then
    raise exception 'One or more app records changed since first-party batch 17 review';
  end if;

  if (
    select count(*)
    from public.self_host_apps a
    join public.self_host_app_resource_estimates r on r.app_id = a.id
    where (a.slug, r.ram_estimate_min_mb, r.ram_estimate_max_mb, r.ram_estimate_basis, r.storage_estimate_min_gb, r.storage_estimate_max_gb, r.storage_estimate_basis) in (
      ('grafanamimir', 2048, 8192, 'A small monolithic deployment runs in one process; ingestion rate and query load drive memory use.', 5, 100, 'Stores retained metrics; ingestion rate and retention period drive storage use.'),
      ('grafanapromtail', 256, 2048, 'Typical small self-hosted instance; workload and stored data vary.', 1, 10, 'Typical small self-hosted instance; workload and stored data vary.'),
      ('kibana', 1024, 8192, 'Small single-node service; data volume and request load vary.', 5, 100, 'Small single-node service; data volume and request load vary.'),
      ('neo4j', 1024, 8192, 'Small single-node service; data volume and request load vary.', 5, 100, 'Small single-node service; data volume and request load vary.'),
      ('postgis', 1024, 8192, 'Small single-node service; data volume and request load vary.', 5, 100, 'Small single-node service; data volume and request load vary.'),
      ('prom-alertmanager', 2048, 8192, 'Typical small self-hosted instance; workload and stored data vary.', 5, 100, 'Typical small self-hosted instance; workload and stored data vary.'),
      ('rancher', 2048, 8192, 'Typical small self-hosted instance; workload and stored data vary.', 1, 20, 'Typical small self-hosted instance; workload and stored data vary.'),
      ('plex', 1024, 8192, 'Plex says 4 GB is typically sufficient and Linux systems may use less; concurrent streams and transcoding affect the range.', 50, 500, 'Small single-node service; active users and stored content vary.'),
      ('collabora-code', 2048, 8192, 'Typical small self-hosted instance; workload and stored data vary.', 50, 500, 'Typical small self-hosted instance; workload and stored data vary.'),
      ('swag', 256, 2048, 'Typical small self-hosted instance; workload and stored data vary.', 1, 20, 'Typical small self-hosted instance; workload and stored data vary.'),
      ('chronograf', 256, 2048, 'Typical small self-hosted instance; workload and stored data vary.', 5, 100, 'Typical small self-hosted instance; workload and stored data vary.'),
      ('watchtower', 2048, 8192, 'Typical small self-hosted instance; workload and stored data vary.', 50, 500, 'Typical small self-hosted instance; workload and stored data vary.')
    )
  ) <> 12 then
    raise exception 'One or more resource estimates changed since first-party batch 17 review';
  end if;

  if not exists (
    select 1 from public.self_host_app_install_options i join public.self_host_apps a on a.id = i.app_id
    where a.slug = 'grafanapromtail' and i.options @> '[{"method":"docker","image":"grafana/promtail","support_level":"community","note":"Community-maintained image. Verify the publisher before pulling."}]'::jsonb
  ) or not exists (
    select 1 from public.self_host_app_install_options i join public.self_host_apps a on a.id = i.app_id
    where a.slug = 'kibana' and i.options @> '[{"method":"docker","image":"docker.elastic.co/kibana/kibana:9.5.4"}]'::jsonb and i.options @> '[{"method":"compose","image":"docker.elastic.co/kibana/kibana:9.5.4"}]'::jsonb
  ) or not exists (
    select 1 from public.self_host_app_install_options i join public.self_host_apps a on a.id = i.app_id
    where a.slug = 'neo4j' and not i.options @> '[{"method":"compose"}]'::jsonb
  ) or not exists (
    select 1 from public.self_host_app_install_options i join public.self_host_apps a on a.id = i.app_id
    where a.slug = 'prom-alertmanager' and i.options @> '[{"method":"docker","image":"prom/alertmanager:latest","support_level":"community","note":"Community-maintained image. Verify the publisher before pulling."}]'::jsonb
  ) or not exists (
    select 1 from public.self_host_app_install_options i join public.self_host_apps a on a.id = i.app_id
    where a.slug = 'rancher' and i.options @> '[{"method":"docker","image":"rancher/rancher:latest","support_level":"community","note":"Community-maintained image. Verify the publisher before pulling."}]'::jsonb
  ) or not exists (
    select 1 from public.self_host_app_install_options i join public.self_host_apps a on a.id = i.app_id
    where a.slug = 'collabora-code' and i.options @> '[{"method":"docker","image":"collabora/code","support_level":"community","note":"Community-maintained image. Verify the publisher before pulling."}]'::jsonb
  ) or not exists (
    select 1 from public.self_host_app_install_options i join public.self_host_apps a on a.id = i.app_id
    where a.slug = 'swag' and not i.options @> '[{"method":"compose"}]'::jsonb and i.options @> '[{"method":"docker","image":"linuxserver/swag","support_level":"community","note":"Community-maintained image. Verify the publisher before pulling."}]'::jsonb
  ) or not exists (
    select 1 from public.self_host_app_install_options i join public.self_host_apps a on a.id = i.app_id
    where a.slug = 'watchtower' and i.options @> '[{"method":"docker","image":"containrrr/watchtower","support_level":"community","note":"Community-maintained image. Verify the publisher before pulling."}]'::jsonb
  ) then
    raise exception 'One or more install options changed since first-party batch 17 review';
  end if;
end;
$review_guard$;

with reviewed as (
  select *
  from jsonb_to_recordset($batch$
  [
    {"slug":"grafanamimir","requires_database":false,"database_types":[],"storage_profile":"depends","persistent_storage":true,"data_source_urls":["https://grafana.com/docs/mimir/latest/get-started/","https://grafana.com/docs/mimir/latest/set-up/hardware-requirements/","https://grafana.com/docs/mimir/latest/manage/run-production-environment/planning-capacity/","https://github.com/grafana/mimir/blob/main/docs/sources/mimir/get-started/play-with-grafana-mimir/docker-compose.yml"],"status_update":{"database":{"status":"published","checked_at":"2026-09-29","confidence":"high","note":"The single-process example uses local filesystem storage; production documentation describes object storage for blocks rather than an external SQL database.","source_urls":["https://grafana.com/docs/mimir/latest/get-started/","https://grafana.com/docs/mimir/latest/set-up/hardware-requirements/"]},"storage":{"status":"published","checked_at":"2026-09-29","confidence":"high","note":"Metrics blocks use object storage, with local persistent disks for WAL and temporary data.","source_urls":["https://grafana.com/docs/mimir/latest/set-up/hardware-requirements/"]},"persistent_storage":{"status":"published","checked_at":"2026-09-29","confidence":"high","note":"Mimir persists TSDB blocks and local WAL data.","source_urls":["https://grafana.com/docs/mimir/latest/set-up/hardware-requirements/"]},"ram":{"status":"not_published","checked_at":"2026-09-29","confidence":"low","note":"Memory depends on series, ingestion, and query load; an app-specific range is stored in the estimate row.","source_urls":["https://grafana.com/docs/mimir/latest/manage/run-production-environment/planning-capacity/"]},"storage_capacity":{"status":"not_published","checked_at":"2026-09-29","confidence":"low","note":"Capacity depends on retained metrics and workload; an app-specific range is stored in the estimate row.","source_urls":["https://grafana.com/docs/mimir/latest/set-up/hardware-requirements/"]}}},
    {"slug":"grafanapromtail","source_code_url":"https://github.com/grafana/loki/tree/v3.6.5/clients/cmd/promtail","requires_database":false,"database_types":[],"storage_profile":"tiny","persistent_storage":true,"docker_support":"official","maintenance_status":"stale","summary":"End-of-life agent for collecting host and container logs and sending them to Grafana Loki.","summary_source":"https://grafana.com/docs/loki/latest/send-data/promtail/","summary_confidence":"high","data_source_urls":["https://grafana.com/docs/loki/latest/send-data/promtail/","https://grafana.com/docs/loki/latest/send-data/promtail/configuration/","https://github.com/grafana/loki/tree/v3.6.5/clients/cmd/promtail","https://github.com/grafana/helm-charts/blob/main/charts/promtail/values.yaml"],"status_update":{"database":{"status":"published","checked_at":"2026-09-29","confidence":"high","note":"Promtail reads log sources and sends entries to Loki; it does not require a database service.","source_urls":["https://grafana.com/docs/loki/latest/send-data/promtail/"]},"storage":{"status":"published","checked_at":"2026-09-29","confidence":"medium","note":"Promtail stores tracking positions locally; log retention belongs to Loki.","source_urls":["https://grafana.com/docs/loki/latest/send-data/promtail/configuration/"]},"persistent_storage":{"status":"published","checked_at":"2026-09-29","confidence":"medium","note":"The positions file can be kept between restarts to avoid rereading log files.","source_urls":["https://grafana.com/docs/loki/latest/send-data/promtail/configuration/"]},"docker":{"status":"published","checked_at":"2026-09-29","confidence":"high","note":"Grafana publishes the grafana/promtail image.","source_urls":["https://github.com/grafana/helm-charts/blob/main/charts/promtail/values.yaml","https://hub.docker.com/r/grafana/promtail/"]},"maintenance":{"status":"published","checked_at":"2026-09-29","confidence":"high","note":"Promtail reached end of life on March 2, 2026; Grafana directs us