    {"slug":"kibana","docker_image":"docker.elastic.co/kibana/kibana:9.4.4","requires_database":true,"database_types":["elasticsearch"],"storage_profile":"low","persistent_storage":true,"ram_recommended_mb":2048,"resource_requirement_kind":"official_recommended","data_source_urls":["https://www.elastic.co/docs/deploy-manage/deploy/self-managed/install-kibana-with-docker","https://www.elastic.co/docs/deploy-manage/production-guidance/kibana-configure-memory","https://www.elastic.co/docs/deploy-manage/production-guidance/kibana-traffic-scaling-considerations"],"status_update":{"database":{"status":"published","checked_at":"2026-09-29","confidence":"high","note":"Kibana connects to Elasticsearch for its saved objects and data.","source_urls":["https://www.elastic.co/docs/deploy-manage/deploy/self-managed/install-kibana-with-docker"]},"storage":{"status":"published","checked_at":"2026-09-29","confidence":"medium","note":"Local data is used for the secure-settings keystore; Elasticsearch stores dashboards and search data.","source_urls":["https://www.elastic.co/docs/deploy-manage/deploy/self-managed/install-kibana-with-docker"]},"persistent_storage":{"status":"published","checked_at":"2026-09-29","confidence":"medium","note":"Elastic documents mounting the config and data directories to preserve the secure-settings keystore.","source_urls":["https://www.elastic.co/docs/deploy-manage/deploy/self-managed/install-kibana-with-docker"]},"docker":{"status":"published","checked_at":"2026-09-29","confidence":"high","note":"Elastic's current Docker guide uses its registry image.","source_urls":["https://www.elastic.co/docs/deploy-manage/deploy/self-managed/install-kibana-with-docker"]},"compose":{"status":"published","checked_at":"2026-09-29","confidence":"high","note":"Elastic's Docker guide includes Docker Compose configuration.","source_urls":["https://www.elastic.co/docs/deploy-manage/deploy/self-managed/install-kibana-with-docker"]},"ram":{"status":"published","checked_at":"