":"2026-09-29","confidence":"high","note":"Neo4j lists 2 GB minimum and 16 GB or more recommended for personal and development use.","source_urls":["https://neo4j.com/docs/operations-manual/current/installation/requirements/"]},"storage_capacity":{"status":"published","checked_at":"2026-09-29","confidence":"high","note":"Neo4j lists 10 GB minimum for personal and development use; actual size depends on the graph.","source_urls":["https://neo4j.com/docs/operations-manual/current/installation/requirements/"]}}},
    {"slug":"postgis","requires_database":true,"database_types":["postgres"],"storage_profile":"high","persistent_storage":true,"data_source_urls":["https://postgis.net/documentation/getting_started/","https://postgis.net/documentation/getting_started/install_docker/"],"status_update":{"database":{"status":"published","checked_at":"2026-09-29","confidence":"high","note":"PostGIS is a PostgreSQL extension that is enabled in a PostgreSQL database.","source_urls":["https://postgis.net/documentation/getting_started/"]},"storage":{"status":"published","checked_at":"2026-09-29","confidence":"high","note":"Spatial data and indexes are stored in PostgreSQL database files.","source_urls":["https://postgis.net/documentation/getting_started/","https://postgis.net/documentation/getting_started/install_docker/"]},"persistent_storage":{"status":"published","checked_at":"2026-09-29","confidence":"high","note":"The PostGIS Docker build runs PostgreSQL, whose database files need persistent storage.","source_urls":["https://postgis.net/documentation/getting_started/install_docker/"]},"ram":{"status":"not_published","checked_at":"2026-09-29","confidence":"low","note":"The project does not give a universal RAM size; the estimate is for a small PostgreSQL/PostGIS workload.","source_urls":["https://postgis.net/documentation/getting_started/"]},"storage_capacity":{"status":"not_published","checked_at":"2026-09-29","confidence":"low","note":"Spatial dataset size varies; the app-specific range is stored in the estimate row.","source_urls":["https://postgis.net/documentation/getting_started/"]}}},
