["https://github.com/containrrr/watchtower"]}}}
  ]
  $batch$::jsonb)
  as r(
    slug text,
    requires_database boolean,
    database_types text[],
    storage_profile text,
    persistent_storage boolean,
    docker_support text,
    compose_support boolean,
    compose_url text,
    docker_url text,
    docker_image text,
    docs_url text,
    install_docs_url text,
    source_code_url text,
    maintenance_status text,
    summary text,
    summary_source text,
    summary_confidence text,
    ram_min_mb integer,
    ram_recommended_mb integer,
    storage_min_gb numeric,
    resource_requirement_kind text,
    data_source_urls text[],
    status_update jsonb
  )
)
update public.self_host_apps a
set requires_database = coalesce(r.requires_database, a.requires_database),
    database_types = coalesce(r.database_types, a.database_types),
    storage_profile = coalesce(r.storage_profile, a.storage_profile),
    persistent_storage = coalesce(r.persistent_storage, a.persistent_storage),
    docker_support = coalesce(r.docker_support, a.docker_support),
    compose_support = coalesce(r.compose_support, a.compose_support),
    compose_url = coalesce(r.compose_url, a.compose_url),
    docker_url = coalesce(r.docker_url, a.docker_url),
    docker_image = coalesce(r.docker_image, a.docker_image),
    docs_url = coalesce(r.docs_url, a.docs_url),
    install_docs_url = coalesce(r.install_docs_url, a.install_docs_url),
    source_code_url = coalesce(r.source_code_url, a.source_code_url),
    maintenance_status = coalesce(r.maintenance_status, a.maintenance_status),
    summary = coalesce(r.summary, a.summary),
    summary_source = coalesce(r.summary_source, a.summary_source),
    summary_confidence = coalesce(r.summary_confidence, a.summary_confidence),
    ram_min_mb = coalesce(r.ram_min_mb, a.ram_min_mb),
    ram_recommended_mb = coalesce(r.ram_recommended_mb, a.ram_recommended_mb),
    storage_min_gb = coalesce(r.storage_min_gb, a.storage_min_gb),
    resource_requirement_kind = coalesce(r.resource_requirement_kind, a.resource_requirement_kind),
    data_source_urls = array(
      select distinct s.url
      from unnest(coalesce(a.data_source_urls, array[]::text[]) || coalesce(r.data_source_urls, array[]::text[])) as s(url)
      order by s.url
    ),
    technical_fact_status = coalesce(a.technical_fact_status, '{}'::jsonb) || coalesce(r.status_update, '{}'::jsonb),
    updated_at = now()
from reviewed r
where a.slug = r.slug;

with reviewed(
  slug, ram_min, ram_max, ram_confidence, ram_basis, ram_sources,
  storage_min, storage_max, storage_confidence, storage_basis, storage_sources
) as (values
  ('grafanamimir', 2048::numeric, 8192::numeric, 'low', 'A small monolithic metrics deployment; active series, ingestion rate, and query load drive memory use.', array['https://grafana.com/docs/mimir/latest/manage/run-production-environment/planning-capacity/','https://grafana.com/docs/mimir/latest/set-up/hardware-requirements/']::text[], 10::numeric, 100::numeric, 'low', 'Stores retained metric blocks; ingestion rate, retention, and object storage determine capacity.', array['https://grafana.com/docs/mimir/latest/set-up/hardware-requirements/','https://grafana.com/docs/mimir/latest/get-started/']::text[]),
  ('grafanapromtail', 128, 512, 'low', 'A single log-shipping agent; scrape volume, labels, and batching affect memory use.', array['https://grafana.com/docs/loki/latest/send-data/promtail/','https://github.com/grafana/helm-charts/blob/main/charts/promtail/values.yaml']::text[], 1, 5, 'low', 'Promtail keeps a small positions file and configuration; log retention belongs to Loki.', array['https://grafana.com/docs/loki/latest/send-data/promtail/configuration/','https://grafana.com/docs/loki/latest/send-data/promtail/']::text[]),
  ('kibana', 1024, 4096, 'medium', 'Elastic''s default is sufficient for core use; heavier reporting, alerting, and concurrent analysis need more memory.', array['https://www.elastic.co/docs/deploy-manage/production-guidance/kibana-configure-memory','https://www.elastic.co/docs/deploy-manage/production-guidance/kibana-traffic-scaling-considerations']::text[], 1, 10, 'low', 'Kibana keeps local config, cache, and optional secure settings; dashboards and search data live in Elasticsearch.', array['https://www.elastic.co/docs/deploy-manage/deploy/self-managed/install-kibana-with-docker']::text[]),
  ('neo4j', 2048, 16384, 'medium', 'Neo4j lists 2 GB minimum and 16 GB or more recommended for personal or development use; graph size and queries affect use.', array['https://neo4j.com/docs/operations-manual/current/installation/requirements/']::text[], 10, 100, 'medium', 'Neo4j lists 10 GB minimum for personal use; graph data and indexes determine growth.', array['https://neo4j.com/docs/operations-manual/current/installation/requirements/','https://neo4j.com/docs/operations-manual/current/docker/mounting-volumes/']::text[]),
  ('postgis', 1024, 8192, 'low', 'PostGIS runs inside PostgreSQL; spatial queries and concurrent work affect the database memory footprint.', array['https://postgis.net/documentation/getting_started/','https://postgis.net/documentation/getting_started/install_docker/']::text[], 10, 100, 'low', 'Spatial data and indexes are stored in PostgreSQL; dataset size determines growth.', array['https://postgis.net/documentation/getting_started/','https://postgis.net/documentation/getting_started/install_docker/']::text[]),
  ('prom-alertmanager', 128, 512, 'low', 'A small Alertmanager instance routes grouped alerts; active alerts and receiver integrations affect memory use.', array['https://prometheus.io/docs/alerting/latest/alertmanager/','https://hub.docker.com/r/prom/alertmanager']::text[], 1, 5, 'medium', 'Local storage holds silence snapshots and the notification log; alert payloads are not retained there.', array['https://prometheus.io/docs/alerting/latest/high_availability/','https://hub.docker.com/r/prom/alertmanager']::text[]),
  ('rancher', 4096, 16384, 'low', 'The server footprint grows with managed clusters, nodes, workloads, and users; estimate is for a small test or homelab setup.', array['https://ranchermanager.docs.rancher.com/getting-started/installation-and-upgrade/installation-requirements/','https://ranchermanager.docs.rancher.com/getting-started/installation-and-upgrade/other-installation-methods/rancher-on-a-single-node-with-docker/']::text[], 20, 100, 'low', 'Rancher persists its local cluster and management state; cluster count and managed workloads drive growth.', array['https://ranchermanager.docs.rancher.com/getting-started/installation-and-upgrade/installation-requirements/','https://ranchermanager.docs.rancher.com/getting-started/installation-and-upgrade/other-installation-methods/rancher-on-a-single-node-with-docker/']::text[]),
  ('plex', 1024, 8192, 'medium', 'Plex says 4 GB is typically sufficient; concurrent streams and video transcoding can raise memory use.', array['https://support.plex.tv/articles/200375666-plex-media-server-requirements/']::text[], 100, 2000, 'low', 'Media libraries dominate storage; metadata and media files grow with the size and quality of the collection.', array['https://support.plex.tv/articles/200375666-plex-media-server-requirements/','https://support.plex.tv/articles/202915258-where-is-the-plex-media-server-data-directory-located/']::text[]),
  ('collabora-code', 2048, 8192, 'low', 'CODE renders and edits documents in browser sessions; concurrent editors and document size drive memory use.', array['https://sdk.collaboraonline.com/docs/installation/CODE_Docker_image.html','https://www.collaboraonline.com/code/']::text[], 1, 10, 'low', 'CODE needs room for its image, configuration, and temporary session files; documents stay on the connected WOPI host.', array['https://sdk.collaboraonline.com/docs/installation/CODE_Docker_image.html','https://www.collaboraonline.com/code/']::text[]),
  ('swag', 128, 512, 'low', 'A small reverse proxy and certificate service; enabled add-ons and request load affect memory use.', array['https://docs.linuxserver.io/images/docker-swag/']::text[], 1, 10, 'medium', 'The persistent config folder holds proxy configuration, certificates, and optional fail2ban state.', array['https://docs.linuxserver.io/images/docker-swag/']::text[]),
  ('chronograf', 128, 512, 'low', 'A small web interface for InfluxDB; dashboard use and concurrent users drive memory use.', array['https://docs.influxdata.com/chronograf/v1/introduction/installation/','https://docs.influxdata.com/chronograf/v1/administration/config-options/']::text[], 1, 10, 'medium', 'Chronograf stores dashboards, connections, and settings in its local Bolt database.', array['https://docs.influxdata.com/chronograf/v1/administration/config-options/','https://docs.influxdata.com/chronograf/v1/administration/restoring-chronograf-db/']::text[]),
  ('watchtower', 64, 256, 'low', 'A small background service checks image registries and controls Docker containers through the socket.', array['https://github.com/containrrr/watchtower','https://hub.docker.com/r/containrrr/watchtower']::text[], 1, 5, 'low', 'Watchtower does not retain container data; storage covers its image, configuration, and logs.', array['https://github.com/containrrr/watchtower','https://hub.docker.com/r/containrrr/watchtower']::text[])
)
update public.self_host_app_resource_estimates r
set ram_estimate_min_mb = v.ram_min,
    ram_estimate_max_mb = v.ram_max,
    ram_estimate_kind = 'estimated',
    ram_estimate_confidence = v.ram_confidence,
    ram_estimate_basis = v.ram_basis,
    ram_source_urls = v.ram_sources,
    storage_estimate_min_gb = v.storage_min,
    storage_estimate_max_gb = v.storage_max,
    storage_estimate_kind = 'estimated',
    storage_estimate_confidence = v.storage_confidence,
    storage_estimate_basis = v.storage_basis,
    storage_source_urls = v.storage_sources,
    checked_at = now(),
    updated_at = now()
from public.self_host_apps a
join reviewed v on v.slug = a.slug
where r.app_id = a.id;

update public.self_host_app_install_options i
set options = (
  select jsonb_agg(
    case
      when a.slug = 'grafanapromtail' and e->>'method' = 'docker' then jsonb_set(jsonb_set(e, '{support_level}', '"official"'::jsonb), '{note}', '"Grafana announced end of life on March 2, 2026."'::jsonb)
      when a.slug in ('prom-alertmanager','collabora-code','watchtower') and e->>'method' = 'docker' then jsonb_set(jsonb_set(e, '{support_level}', '"official"'::jsonb), '{note}', 'null'::jsonb)
      when a.slug = 'rancher' and e->>'method' = 'docker' then jsonb_set(jsonb_set(e, '{support_level}', '"official"'::jsonb), '{note}', '"The single-node Docker install is for testing and development."'::jsonb)
      when a.slug = 'swag' and e->>'method' = 'docker' then jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(e, '{image}', to_jsonb('lscr.io/linuxserver/swag:latest'::text)), '{url}', to_jsonb('https://docs.linuxserver.io/images/docker-swag/'::text)), '{source_url}', to_jsonb('https://docs.linuxserver.io/images/docker-swag/'::text)), '{support_level}', '"official"'::jsonb), '{note}', 'null'::jsonb)
      else e
    end order by (e->>'sort_order')::integer
  )
  from jsonb_array_elements(i.options) e
  ),
  checked_at = now(),
  updated_at = now()
from public.self_host_apps a
where a.id = i.app_id and a.slug in ('grafanapromtail','prom-alertmanager','rancher','collabora-code','swag','watchtower');

update public.self_host_app_install_options i
set docker_images = array['lscr.io/linuxserver/swag:latest']::text[],
    docker_urls = array['https://docs.linuxserver.io/images/docker-swag/']::text[],
    compose_urls = array['https://docs.linuxserver.io/images/docker-swag/']::text[],
    source_urls = array(
      select distinct s.url from unnest(coalesce(i.source_urls,array[]::text[]) || array['https://docs.linuxserver.io/images/docker-swag/','https://github.com/linuxserver/docker-swag']::text[]) as s(url) order by s.url
    ),
    options = i.options || jsonb_build_array(jsonb_build_object(
      'method','compose','label','Docker Compose','url','https://docs.linuxserver.io/images/docker-swag/','image','lscr.io/linuxserver/swag:latest','support_level','official','sort_order',20,'source_url','https://docs.linuxserver.io/images/docker-swag/','note',null
    )),
    checked_at = now(),
    updated_at = now()
from public.self_host_apps a where a.id = i.app_id and a.slug = 'swag';

update public.self_host_app_install_options i
set compose_urls = array['https://neo4j.com/docs/operations-manual/current/docker/docker-compose-standalone/']::text[],
    source_urls = array(
      select distinct s.url from unnest(coalesce(i.source_urls,array[]::text[]) || array['https://neo4j.com/docs/operations-manual/current/docker/docker-compose-standalone/']::text[]) as s(url) order by s.url
    ),
    options = i.options || jsonb_build_array(jsonb_build_object(
      'method','compose','label','Docker Compose','url','https://neo4j.com/docs/operations-manual/current/docker/docker-compose-standalone/','image','neo4j:latest','support_level','official','sort_order',20,'source_url','https://neo4j.com/docs/operations-manual/current/docker/docker-compose-standalone/','note',null
    )),
    checked_at = now(),
    updated_at = now()
from public.self_host_apps a where a.id = i.app_id and a.slug = 'neo4j';

commit;
